#!/usr/bin/env bash
set -Eeuo pipefail

ROOT="${1:-/root/hyper-hosting-panel}"
SID="${2:-25}"
PUBLIC="90.189.208.25"
LAN="192.168.0.179"
SRC_CTL="$ROOT/cs16-panel/bin/hyper-cs16-ctl"
LIVE_CTL="/usr/local/sbin/hyper-cs16-ctl"
SERVER_ROOT="/srv/hyper-cs16/servers/$SID"
CSTRIKE="$SERVER_ROOT/cstrike"
FASTDL="/srv/hyper-cs16/fastdl/$SID"
STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="/root/hyper-cs16-fastdl-final-v8-${STAMP}"

[[ ${EUID:-$(id -u)} -eq 0 ]] || { echo "[ERROR] run as root"; exit 1; }
[[ -f "$SRC_CTL" ]] || { echo "[ERROR] missing controller: $SRC_CTL"; exit 2; }
[[ -d "$CSTRIKE/maps" ]] || { echo "[ERROR] missing maps directory: $CSTRIKE/maps"; exit 2; }

mkdir -p "$BACKUP"
cp -a "$SRC_CTL" "$BACKUP/hyper-cs16-ctl.repo"
[[ -f "$LIVE_CTL" ]] && cp -a "$LIVE_CTL" "$BACKUP/hyper-cs16-ctl.live"
[[ -f "$CSTRIKE/server.cfg" ]] && cp -a "$CSTRIKE/server.cfg" "$BACKUP/server.cfg"

echo "================================================================"
echo " HYPER-HOST FASTDL FINAL v8"
echo " Server: #$SID"
echo " URL:    http://$PUBLIC/fastdl/$SID/"
echo " Backup: $BACKUP"
echo "================================================================"

echo "[1/10] Validate SOURCE BSP files..."
python3 - "$CSTRIKE/maps" <<'PY'
from pathlib import Path
import sys
root=Path(sys.argv[1])
good=[]; bad=[]
for p in sorted(root.glob('*.bsp')):
    try:
        with p.open('rb') as f:
            head=f.read(4)
        ver=int.from_bytes(head,'little') if len(head)==4 else None
        if ver==30:
            good.append(p.name)
        else:
            bad.append((p.name,ver,head.hex(),p.stat().st_size))
    except Exception as e:
        bad.append((p.name,None,str(e),0))
print("valid BSP:",len(good))
print("bad BSP:",len(bad))
if bad:
    for x in bad[:50]: print("BAD",x)
    raise SystemExit(20)
PY

echo "[2/10] Configure one authoritative nginx FastDL vhost for the PUBLIC IP..."
NGPY="$(mktemp)"
echo '' | base64 -d > "$NGPY"
python3 "$NGPY" "$BACKUP"
rm -f "$NGPY"

echo "[3/10] Patch panel with a final FastDL override..."
PATCHER="$(mktemp)"
echo '' | base64 -d > "$PATCHER"
python3 "$PATCHER" "$SRC_CTL"
python3 -m py_compile "$SRC_CTL"
install -m 0755 "$SRC_CTL" "$LIVE_CTL"
python3 -m py_compile "$LIVE_CTL"
rm -f "$PATCHER"

echo "[4/10] Firewall..."
if command -v ufw >/dev/null 2>&1; then
  ufw allow 80/tcp >/dev/null 2>&1 || true
fi

echo "[5/10] Clean FastDL sync..."
"$LIVE_CTL" fastdl-sync "$SID"

echo "[6/10] Verify source == FastDL BSP checksums..."
python3 - "$CSTRIKE/maps" "$FASTDL/maps" <<'PY'
from pathlib import Path
import hashlib,sys
src=Path(sys.argv[1]); dst=Path(sys.argv[2])
def sha(p):
    h=hashlib.sha256()
    with p.open('rb') as f:
        for c in iter(lambda:f.read(1024*1024),b''):
            h.update(c)
    return h.hexdigest()
sm={p.name:sha(p) for p in src.glob('*.bsp')}
dm={p.name:sha(p) for p in dst.glob('*.bsp')}
bad=[n for n,h in sm.items() if dm.get(n)!=h]
extra=sorted(set(dm)-set(sm))
print("source maps:",len(sm))
print("fastdl maps:",len(dm))
print("mismatched:",len(bad))
print("extra:",len(extra))
if bad or extra:
    print("BAD:",bad)
    print("EXTRA:",extra)
    raise SystemExit(21)
PY

echo "[7/10] Verify EVERY BSP through nginx using Host: $PUBLIC ..."
python3 - "$FASTDL/maps" "$SID" <<'PY'
from pathlib import Path
import urllib.request,urllib.error,urllib.parse,sys
maps=Path(sys.argv[1]); sid=int(sys.argv[2])
bad=[]; good=0
for p in sorted(maps.glob('*.bsp')):
    url='http://127.0.0.1/fastdl/%d/maps/%s'%(sid,urllib.parse.quote(p.name,safe='._-+()[]'))
    req=urllib.request.Request(url,headers={'Host':'90.189.208.25','Range':'bytes=0-3','User-Agent':'HYPER-HOST-FastDL-v8'})
    code=0; head=b''; marker=''
    try:
        with urllib.request.urlopen(req,timeout=5) as r:
            code=int(getattr(r,'status',200) or 200)
            head=r.read(4)
            marker=str(r.headers.get('X-Hyper-FastDL') or '')
    except urllib.error.HTTPError as e:
        code=e.code
        head=e.read(4)
    except Exception as e:
        bad.append((p.name,0,None,'',str(e)))
        continue
    ver=int.from_bytes(head,'little') if len(head)==4 else None
    if code not in (200,206) or ver!=30 or marker!='raw':
        bad.append((p.name,code,ver,head.hex(),marker))
    else:
        good+=1
print("HTTP raw BSP OK:",good)
print("HTTP raw BSP BAD:",len(bad))
if bad:
    for x in bad[:50]: print("BAD",x)
    raise SystemExit(22)
PY

echo "[8/10] Restart CS server and re-apply runtime FastDL..."
systemctl restart "hyper-cs16@${SID}.service"
sleep 3
"$LIVE_CTL" fastdl-sync "$SID"

echo "[9/10] Panel status..."
"$LIVE_CTL" fastdl-status "$SID"

echo "[10/10] Runtime cvars..."
"$LIVE_CTL" rcon "$SID" "sv_downloadurl" || true
"$LIVE_CTL" rcon "$SID" "sv_allowdownload" || true
"$LIVE_CTL" rcon "$SID" "sv_allow_dlfile" || true

echo
echo "Direct local HTTP proof:"
PROBE="$(find "$FASTDL/maps" -maxdepth 1 -type f -name 'zm_303.bsp' -print -quit)"
[[ -n "$PROBE" ]] || PROBE="$(find "$FASTDL/maps" -maxdepth 1 -type f -name '*.bsp' -print -quit)"
if [[ -n "$PROBE" ]]; then
  NAME="$(basename "$PROBE")"
  curl -sS -D /tmp/hh-fastdl-v8.headers -H "Host: $PUBLIC" --range 0-3 "http://127.0.0.1/fastdl/$SID/maps/$NAME" -o /tmp/hh-fastdl-v8.head
  sed -n '1,20p' /tmp/hh-fastdl-v8.headers
  echo -n "First 4 bytes: "
  xxd -p -l4 /tmp/hh-fastdl-v8.head
  echo -n "BSP version: "
  python3 - <<'PY'
from pathlib import Path
b=Path('/tmp/hh-fastdl-v8.head').read_bytes()[:4]
print(int.from_bytes(b,'little') if len(b)==4 else None)
PY
  rm -f /tmp/hh-fastdl-v8.headers /tmp/hh-fastdl-v8.head
fi

echo
echo "================================================================"
echo " [SUCCESS] FASTDL FINAL v8"
echo "================================================================"
echo "URL: http://$PUBLIC/fastdl/$SID/"
echo "Source BSP and FastDL BSP are byte-identical."
echo "Every published BSP returned GoldSrc version 30 through nginx."
echo "The panel fastdl-sync/status commands now use the same verification."
echo "Backup: $BACKUP"
echo
echo "NOTE: old-zombie.ru / SSL / HTTPS is NOT used for FastDL."
echo "External clients need TCP 80 forwarded to $LAN:80."
